(function(){
  const D=window.SingularDemo, config=window.SINGULAR_TESTNET_CONFIG||{dataMode:'demo'}, onchain=config.dataMode==='onchain', mainnet=onchain&&config.chainId===56;
  const networkName=mainnet?'BNB Chain Mainnet':'BNB Chain Testnet', networkLabel=mainnet?'BSC MAINNET':'BSC TESTNET', unit=mainnet?'BNB':'tBNB';
  let provider, bootError=null, ready=!onchain;
  try{provider=onchain?new window.SingularOnchain.OnchainSingularProvider(config):new D.DemoSingularProvider()}catch(error){bootError=error;provider=new D.DemoSingularProvider();ready=false}
  const page=document.body.dataset.page||'home', root=document.getElementById('appRoot');
  let qty=3, filter='ALL', modalState=null, purchaseReceipt=null, observedPoolStates=null, latestSettlement=null, walletDialogOpen=false, walletMenuOpen=false, walletBusy=false, activeWalletName='Browser wallet';
  let renderedWallet=null, renderedPoolStatus=null;
  const observedSales=new Map(), recentSales=new Map();
  function trackSales(){for(const pool of provider.getPools()){const prior=observedSales.get(pool.id);if(prior!=null&&pool.entriesSold>prior)recentSales.set(pool.id,{quantity:pool.entriesSold-prior,time:Date.now()});observedSales.set(pool.id,pool.entriesSold)}}
  const walletChoices=new Map();
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function addWallet(id,name,icon,wallet){if(!wallet?.request)return;const validIcon=/^data:image\/(?:png|jpeg|webp|svg\+xml)[;,]/i.test(icon||'')?icon:null;const existing=[...walletChoices].find(([,choice])=>choice.wallet===wallet);if(existing){const [key,choice]=existing;walletChoices.set(key,{...choice,name:validIcon?name:choice.name,icon:validIcon||choice.icon})}else walletChoices.set(id,{name,icon:validIcon,wallet});if(walletDialogOpen)document.getElementById('walletOptions')?.replaceChildren(...walletOptionNodes())}
  const walletCatalog=[['MetaMask','https://metamask.io/download','M','https://metamask.io/favicon.ico'],['Trust Wallet','https://trustwallet.com/browser-extension','T','https://trustwallet.com/favicon.ico'],['Coinbase Wallet','https://www.coinbase.com/wallet','C','https://www.coinbase.com/favicon.ico'],['OKX Wallet','https://www.okx.com/download','O','https://www.okx.com/favicon.ico']];
  function walletOptionNodes(){const hiddenNames=/^(rabby|binance)( wallet)?$/i;const installed=[...walletChoices].filter(([,choice])=>!hiddenNames.test(choice.name.trim())).map(([id,choice])=>{const button=document.createElement('button');button.className='wallet-choice';button.type='button';button.dataset.walletId=id;button.innerHTML=`<span class="wallet-choice__icon">${choice.icon?`<img src="${esc(choice.icon)}" alt="">`:esc(choice.name.slice(0,1))}</span><span><strong>${esc(choice.name)}</strong><small>Detected in this browser · BNB Chain</small></span><span aria-hidden="true">→</span>`;return button});const availableNames=new Set([...walletChoices.values()].map(choice=>choice.name.toLowerCase()));const notInstalled=walletCatalog.filter(([name])=>![...availableNames].some(found=>found.includes(name.toLowerCase().split(' ')[0]))).map(([name,url,mark,icon])=>{const link=document.createElement('a');link.className='wallet-choice wallet-choice--install';link.href=url;link.target='_blank';link.rel='noopener noreferrer';link.innerHTML=`<span class="wallet-choice__icon wallet-choice__icon--${mark.toLowerCase()}"><img src="${esc(icon)}" alt="" loading="lazy" onerror="this.remove()"><span aria-hidden="true">${mark}</span></span><span><strong>${esc(name)}</strong><small>Get from the official site</small></span><span aria-hidden="true">↗</span>`;return link});return [...installed,...notInstalled]}
  if(onchain){window.addEventListener('eip6963:announceProvider',event=>{const {info,provider:wallet}=event.detail||{};if(info?.uuid&&wallet?.request)addWallet(info.uuid,info.name||'Browser wallet',info.icon,wallet)});window.dispatchEvent(new Event('eip6963:requestProvider'));for(const [i,wallet] of (window.ethereum?.providers||[window.ethereum]).filter(Boolean).entries())addWallet(`legacy-${i}`,wallet.isMetaMask?'MetaMask':wallet.isTrust?'Trust Wallet':wallet.isCoinbaseWallet?'Coinbase Wallet':'Browser wallet',null,wallet)}
  function walletDialog(){return `<div class="wallet-connect-modal${walletDialogOpen?' open':''}" id="walletDialog" role="dialog" aria-modal="true" aria-label="Choose a wallet"><div class="wallet-connect-card"><div class="wallet-connect-head"><div><span class="eyebrow">SINGULAR · ${networkLabel}</span><h2>Choose your wallet</h2></div><button type="button" class="wallet-connect-close" data-action="wallet-dialog-close" aria-label="Close wallet chooser">×</button></div><p>Choose a detected browser wallet. Connection requests account access, not a payment signature. Other wallet links open their official download pages.</p><div class="wallet-options" id="walletOptions"></div><div class="wallet-connect-error" id="walletConnectError" role="alert"></div></div></div>`}
  const money=n=>`${Number(n).toFixed(onchain?8:2).replace(/\.?0+$/,'')} ${onchain?unit:'BNB'}`;
  const timeLeft=p=>{if(p.contractStatus===3)return 'Draw complete';if(p.contractStatus===2)return 'Drawing';if(p.contractStatus===4)return 'Expired';if(!p.deadline)return 'Starts on first entry';const s=Math.max(0,Math.ceil((p.deadline-Date.now())/1000));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`};
  const durationLabel=p=>{const minutes=p.duration/60;return Number.isInteger(minutes)?`${minutes} min`:`${Math.round(p.duration)} sec`};
  const deadlineLabel=p=>p.deadline?new Date(p.deadline).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'After first ticket';
  const poolOrder=(a,b)=>{
    if(a.prizeWei!=null&&b.prizeWei!=null){
      const prizeA=BigInt(a.prizeWei),prizeB=BigInt(b.prizeWei);
      if(prizeA!==prizeB)return prizeA<prizeB?-1:1;
    }else if(a.prize!==b.prize)return a.prize-b.prize;
    return a.id-b.id;
  };
  const poolHref=id=>`pool.html?id=${id}`;
  const currentId=()=>Number(new URLSearchParams(location.search).get('id')||document.body.dataset.poolId||2);
  const position=p=>onchain?(p.myEntries?{wallet:provider.getWallet().address,quantity:p.myEntries,amount:Number(window.SingularOnchain.formatBNB(p.myContributionWei)),ticketIds:p.myTicketIds}:null):(p.participants||[]).find(x=>x.wallet===D.DEMO_WALLET);
  function header(){const w=provider.getWallet(),myPools=onchain?provider.getEntries().length:0,myOutcomes=onchain?provider.getPools().filter(p=>p.myEntries&&p.contractStatus===3).length:0,myRefunds=onchain?provider.getRefunds().filter(p=>!p.claimed).length:0;return `<div class="demo-ribbon">${onchain?mainnet?'BNB CHAIN MAINNET · REAL BNB':'BSC TESTNET · REAL tBNB · NOT MAINNET':'DEMO MODE · LOCAL STATE · NO REAL FUNDS'}</div><header class="subnav"><div class="subnav__inner"><a class="brand" href="../"><img src="../assets/singular-logo.png" alt="SINGULAR"></a><nav class="subnav__links"><a href="./">Pools</a><a href="entries.html">My Entries</a><a href="outcomes.html">Outcomes</a><a href="refunds.html">Refunds</a></nav><div class="subnav__right"><span class="network">● ${onchain?networkLabel:'BNB CHAIN · DEMO'}</span><div class="wallet-wrap"><button class="compact-wallet" id="walletButton" aria-expanded="${walletMenuOpen}" aria-controls="walletMenu">${w.wrongNetwork?`Switch to ${networkName}`:w.connected?D.short(w.address):onchain?'Connect Wallet':'Connect Demo Wallet'}</button>${w.connected?`<div class="wallet-menu${walletMenuOpen?' open':''}" id="walletMenu"><div class="wallet-menu__identity"><span class="data-label">CONNECTED WITH ${esc(activeWalletName)}</span><strong title="${esc(w.address)}">${D.short(w.address)}</strong><small>${networkName}</small></div><div class="wallet-menu__balance"><span>${unit} balance</span><b>${money(w.balance)}</b></div><div class="wallet-menu__stats"><span><b>${myPools}</b><small>Entered pools</small></span><span><b>${myOutcomes}</b><small>Draw records</small></span><span><b>${myRefunds}</b><small>Refunds</small></span></div><a class="wallet-menu__feature" href="wallet.html">View wallet activity <span aria-hidden="true">→</span></a><div class="wallet-menu__links"><a href="entries.html">My tickets</a><a href="outcomes.html">Draw history</a><a href="refunds.html">Refunds</a><a href="${config.explorerUrl}/address/${esc(w.address)}" target="_blank" rel="noopener noreferrer">BscScan ↗</a></div><div class="wallet-menu__actions"><button data-action="copy">Copy address</button><button data-action="switch-account">Switch account</button><button data-action="switch-wallet">Switch wallet</button><button data-action="disconnect">Disconnect</button></div></div>`:''}</div></div></div></header>${onchain?walletDialog():''}`}
  function status(p){return D.deriveStatus(p)}
  function poolCard(p){const fill=Math.min(100,p.entriesSold/p.capacity*100),st=status(p),waiting=!p.deadline,remaining=p.capacity-p.entriesSold,signature=`${p.entriesSold}:${p.contractStatus}:${p.deadline}:${p.myEntries}`;return `<a class="pool-card" href="${poolHref(p.id)}" data-live-signature="${signature}" style="color:inherit;text-decoration:none" aria-label="Inspect pool #${p.id}, ${st}; ${p.entriesSold} sold and ${remaining} remaining"><div class="card-top"><span class="eyebrow">POOL #${String(p.id).padStart(2,'0')}</span><span class="status" data-status="${st}">● ${st}</span></div><h2>${money(p.prize)}</h2><span class="muted">Prize pool</span><div class="pool-card__meta"><div><span class="data-label">Ticket price</span><b>${money(p.entryPrice)}</b></div><div><span class="data-label">Entry window</span><b>${durationLabel(p)}</b></div></div><div class="pool-card__schedule"><div><span>${waiting?'TIMER STARTS':'ENTRY DEADLINE'}</span><strong>${deadlineLabel(p)}</strong></div><div><span>${waiting?'DRAW TRIGGER':'TIME LEFT'}</span><strong ${waiting?'':`data-timer="${p.id}"`}>${waiting?'Full capacity':timeLeft(p)}</strong></div></div><p class="pool-card__rule">${waiting?'First confirmed ticket starts the clock.':'A full pool requests VRF; the result follows its callback.'} If time runs out before full, entries are refundable.</p><div class="row-between" aria-live="polite"><small>${p.entriesSold} / ${p.capacity} tickets sold</small><small>${remaining} available</small></div><div class="progress" role="progressbar" aria-valuenow="${p.entriesSold}" aria-valuemin="0" aria-valuemax="${p.capacity}" aria-label="Tickets sold"><i style="width:${fill}%"></i></div><span class="pool-card__link"><span>Inspect pool</span><span>→</span></span></a>`}
  function emptyPools(hasOpen){const none=onchain&&provider.getPools().length===0;return `<div class="pool-empty" role="status"><div class="pool-empty__content"><span class="eyebrow">${hasOpen?'FILTER STATUS / NO MATCHES':none?'TESTNET / AWAITING FIRST POOL':'POOL STATUS / NO OPEN DRAWS'}</span><h2>${hasOpen?'No pools match this view.':none?'No pools have been created yet.':'No open pools right now.'}</h2><p>${hasOpen?'Other pools may still be accepting entries. Return to the full open-pool list to explore them.':none?'The new testnet Pool Manager is connected. A recurring pool must be created by the fixed administrator wallet before entries can begin.':'The current testnet pools have closed. Confirmed draws remain available in Outcomes, while any eligible refunds appear under Refunds.'}</p><div class="pool-empty__actions">${hasOpen?'<button class="pool-empty__primary" data-filter="ALL">Show all open pools <span aria-hidden="true">→</span></button>':none?'': '<a class="pool-empty__primary" href="outcomes.html">Explore outcomes <span aria-hidden="true">→</span></a>'}${none?'':`<a class="pool-empty__secondary" href="${hasOpen?'outcomes.html':'refunds.html'}">${hasOpen?'View outcomes':'Check refunds'} <span aria-hidden="true">↗</span></a>`}</div></div><div class="pool-empty__visual" aria-hidden="true"><div class="pool-empty__orbit"><div class="pool-empty__core"></div></div><span>${none?'TESTNET CONTRACT · READY FOR FIRST POOL':'ONE POOL · ONE VERIFIED OUTCOME'}</span></div></div>`}
  function home(){
    const all=provider.getPools(),open=all.filter(p=>!['RESOLVING','RESOLVED','EXPIRED'].includes(status(p))),drawing=all.filter(p=>status(p)==='RESOLVING');
    const pools=(filter==='ALL'?open:open.filter(p=>status(p)===filter||(filter==='CONVERGING'&&status(p)==='NEAR RESOLUTION'))).sort(poolOrder);
    const total=all.reduce((a,p)=>a+p.entriesSold,0),liquidity=all.reduce((a,p)=>a+p.entriesSold*p.entryPrice,0);
    root.innerHTML=`${header()}<main class="demo-shell"><div class="demo-head"><div><div class="eyebrow">ACTIVE CONVERGENCE</div><h1>BNB pools,<br>in motion.</h1><p class="lead">Choose a fixed-capacity pool. Every entry is stored in this browser for a complete, transparent product demonstration.</p></div><div class="demo-controls"><button class="text-button" data-action="reset">Reset demo</button></div></div><section class="metrics"><div class="metric"><small>Open pools</small><strong>${open.length}</strong></div><div class="metric"><small>Total entries</small><strong>${total}</strong></div><div class="metric"><small>Demo liquidity</small><strong>${liquidity.toFixed(2)} BNB</strong></div><div class="metric"><small>Provider</small><strong>LOCAL</strong></div></section><div class="notice">Demo data is clearly separated from onchain data. No wallet extension, real transaction, or mainnet balance is used.</div><div class="filters"><button class="${filter==='ALL'?'active':''}" data-filter="ALL">All open</button><button class="${filter==='LIVE'?'active':''}" data-filter="LIVE">Live</button><button class="${filter==='CONVERGING'?'active':''}" data-filter="CONVERGING">Converging</button><button class="${filter==='WAITING'?'active':''}" data-filter="WAITING">Waiting</button></div><section class="pool-grid">${pools.map(poolCard).join('')||emptyPools(open.length>0)}</section>${drawing.length?`<section class="section"><div class="section-title"><h2>Draws in progress</h2><span class="muted">Awaiting verified result</span></div><section class="pool-grid">${drawing.sort(poolOrder).map(poolCard).join('')}</section></section>`:''}${recentEntries()}${recentOutcomes()}</main>`
  }
  function recentEntries(){const rows=[];provider.getPools().forEach(p=>(p.activity||[]).filter(a=>a.type==='ENTRY').slice(0,2).forEach(a=>rows.push({...a,poolId:p.id})));return `<section class="section"><div class="section-title"><h2>Recent entries</h2><a href="entries.html">View mine →</a></div><div class="table-card">${rows.length?rows.sort((a,b)=>b.time-a.time).slice(0,5).map(a=>`<div class="table-row"><span data-label="Pool">Pool #${a.poolId}</span><span data-label="Activity">${esc(a.text)}</span><span data-label="Wallet">${onchain?esc(D.short(a.wallet)):a.wallet===D.DEMO_WALLET?'Your demo wallet':'Demo participant'}</span><span data-label="Time">${new Date(a.time).toLocaleTimeString()}</span><span data-label="Source">${onchain?`<a href="${config.explorerUrl}/tx/${a.transactionHash}" target="_blank" rel="noreferrer">Tx ↗</a>`:'DEMO'}</span></div>`).join(''):`<div class="empty">${onchain&&provider.logScanError?'Event history is temporarily unavailable from this RPC. Pool totals above are read directly from the contract.':'No entries yet.'}</div>`}</div></section>`}
  function recentOutcomes(){const rows=provider.getOutcomes().slice().sort((a,b)=>b.id-a.id).slice(0,5);return `<section class="section"><div class="section-title"><h2>Recent outcomes</h2><a href="outcomes.html">View all →</a></div><div class="table-card">${rows.map(p=>`<a class="table-row" href="result.html?id=${p.id}"><span data-label="Pool">Pool #${p.id}</span><span data-label="Prize">${money(p.prize)}</span><span data-label="Ticket">#${p.winningTicket}</span><span data-label="Winner">${esc(p.winner)}</span><span data-label="State">Resolved</span></a>`).join('')||'<div class="empty">No outcomes yet.</div>'}</div></section>`}
  function poolPage(){const p=provider.getPool(currentId());if(!p){root.innerHTML=header()+`<main class="demo-shell"><div class="empty">Pool not found.</div></main>`;return}const pos=position(p),remaining=p.capacity-p.entriesSold,st=status(p),fill=p.entriesSold/p.capacity*100;qty=Math.max(1,Math.min(qty,Math.max(1,remaining)));root.innerHTML=`${header()}<main class="demo-shell"><a href="./" class="back-link">← All pools</a><div class="detail-layout"><div><section class="demo-card pool-hero"><div><span class="eyebrow">POOL #${String(p.id).padStart(2,'0')} · <span class="status" data-status="${st}">${st}</span></span><h1>${p.prize.toFixed(2)} BNB</h1><p class="lead">Fixed-capacity demo pool with deterministic local settlement.</p><div class="progress"><i style="width:${fill}%"></i></div><div class="row-between"><span>${p.entriesSold} / ${p.capacity} entries</span><strong data-timer="${p.id}">${timeLeft(p)}</strong></div></div><div class="singular-pool-orbital is-detail" data-singular-pool data-pool-id="${p.id}" data-fill="${fill}" data-status="${st}"></div></section><section class="demo-card facts"><div class="fact"><span class="data-label">Entry price</span><b>${money(p.entryPrice)}</b></div><div class="fact"><span class="data-label">Protocol fee</span><b>${money(p.fee)}</b></div><div class="fact"><span class="data-label">Capacity</span><b>${p.capacity}</b></div><div class="fact"><span class="data-label">Remaining</span><b>${remaining}</b></div></section>${activity(p)}${distribution(p)}${positionPanel(p,pos)}</div>${entryPanel(p,pos,remaining,st)}</div></main>${modal()}`;if(window.SingularPoolVisual)window.SingularPoolVisual.init()}
  function activity(p){return `<section class="demo-card"><div class="section-title"><h2>Activity</h2><span class="muted">${onchain?'Testnet events':'Demo events'}</span></div><div class="activity-list">${(p.activity||[]).map(a=>`<div class="activity-item"><span class="eyebrow">${a.type}</span><b>${esc(a.text)}</b><time class="muted">${new Date(a.time).toLocaleTimeString()}</time></div>`).join('')||`<div class="empty">${onchain&&provider.logScanError?'Event history temporarily unavailable from RPC.':'No activity yet.'}</div>`}</div></section>`}
  function distribution(p){return `<section class="demo-card"><div class="section-title"><h2>Entry distribution</h2><span class="muted">${p.participants.length?`${p.participants.length} participants · onchain ledger`:onchain&&provider.logScanError?'Ticket owners loading':`${p.participants.length} participants`}</span></div><div class="distribution">${p.participants.map(x=>{const pct=D.chance(x.quantity,p.entriesSold);return `<div class="distribution-row"><div class="distribution-row__wallet" title="${esc(x.wallet)}"><strong>${x.wallet===D.DEMO_WALLET?'YOU · DEMO':esc(D.short(x.wallet))}</strong><small>${x.quantity} ${x.quantity===1?'ticket':'tickets'}</small></div><div class="progress" role="img" aria-label="${pct.toFixed(1)}% of tickets"><i style="width:${pct}%"></i></div><b>${pct.toFixed(1)}%</b></div>`}).join('')||`<div class="empty">${onchain&&provider.logScanError?'Ticket-owner lookup is pending or unavailable.':p.entriesSold?'Participant records are loading.':'Be the first entry.'}</div>`}</div></section>`}
  function positionPanel(p,pos){const ids=onchain?(p.myTicketIds||[]):pos?Array.from({length:pos.quantity},(_,i)=>pos.start+i):[];return `<section class="demo-card position-card"><div class="section-title"><h2>Your position</h2><span class="muted">${onchain?'Connected wallet':'Demo wallet'}</span></div><div class="position-grid"><div class="position-item"><span class="data-label">Tickets owned</span><b>${pos?pos.quantity:0}</b></div><div class="position-item"><span class="data-label">Winning chance</span><b>${D.chance(pos?.quantity||0,p.capacity).toFixed(2)}%</b></div><div class="position-item"><span class="data-label">BNB entered</span><b>${money(pos?.amount||0)}</b></div><div class="position-item"><span class="data-label">Pool share</span><b>${D.chance(pos?.quantity||0,p.entriesSold).toFixed(2)}%</b></div></div><div class="owned-tickets"><span class="data-label">Your ticket numbers</span><div class="ticket-list">${ids.length?ids.map(id=>`<span class="ticket-chip">#${id}</span>`).join(''):'<span class="muted">Buy tickets to see your assigned numbers here.</span>'}</div></div><p class="position-note">Winning chance = your tickets ÷ pool capacity. Ticket numbers are assigned sequentially when the transaction confirms.</p></section>`}
  function entryPanel(p,pos,remaining,st){const w=provider.getWallet(),eligible=['WAITING','LIVE','CONVERGING','NEAR RESOLUTION'].includes(st);return `<aside class="entry-panel"><span class="eyebrow">ENTER POOL</span><h2>Choose quantity</h2><div class="line-item"><span>Entry price</span><b>${money(p.entryPrice)}</b></div><div class="quantity"><button data-action="minus">−</button><strong>${qty}</strong><button data-action="plus">+</button></div><div class="quick">${[1,3,5].map(n=>`<button data-qty="${n}">${n}</button>`).join('')}<button data-qty="${remaining}">MAX</button></div><div class="line-item"><span>Cost</span><b>${money(qty*p.entryPrice)}</b></div><div class="line-item"><span>Entries after</span><b>${(pos?.quantity||0)+qty}</b></div><div class="line-item"><span>Projected odds</span><b>${D.chance((pos?.quantity||0)+qty,p.capacity).toFixed(2)}%</b></div><p class="entry-ticket-note">Ticket numbers are assigned onchain after confirmation and then shown in Your position.</p><div class="error" id="entryError"></div><button class="primary-action" data-action="${w.connected?'review':'connect'}" ${eligible?'':'disabled'}>${w.connected?'REVIEW ENTRY':'CONNECT DEMO WALLET'}</button><p class="muted" style="font-size:11px;line-height:1.5">Local product demo only. No real BNB is sent.</p></aside>`}
  function modal(){if(purchaseReceipt){const r=purchaseReceipt;return `<div class="modal is-open" id="txModal" role="dialog" aria-modal="true" aria-label="Entry confirmed"><div class="modal-card receipt-card"><div class="receipt-mark" aria-hidden="true">✦</div><span class="eyebrow">ENTRY CONFIRMED · ${onchain?networkLabel:'DEMO'}</span><h2>Your tickets are recorded.</h2><p class="receipt-intro">Pool #${r.poolId} · ${r.quantity} ${r.quantity===1?'ticket':'tickets'} purchased</p><div class="receipt-facts"><div><span>Ticket numbers</span><strong>${r.ids.length?r.ids.map(id=>`#${id}`).join(' · '):'View in Your position'}</strong></div><div><span>Your total tickets</span><strong>${r.owned}</strong></div><div><span>Winning chance at capacity</span><strong>${r.odds}</strong></div><div><span>BNB paid</span><strong>${r.cost}</strong></div></div>${r.hash?`<a class="tx-explorer-link" href="${config.explorerUrl}/tx/${r.hash}" target="_blank" rel="noopener noreferrer">View confirmed transaction on BscScan <span>↗</span></a>`:''}<div class="modal-actions"><button class="primary-action" data-action="close-receipt">View my position <span aria-hidden="true">→</span></button></div></div></div>`;}return `<div class="modal" id="txModal" role="dialog" aria-modal="true" aria-label="Review entry"><div class="modal-card"><div class="section-title"><div><span class="eyebrow">REVIEW MAINNET ENTRY</span><h2>Confirm entry</h2></div><button class="text-button" data-action="close">Close</button></div><div id="txSummary"></div><div class="tx-steps" id="txSteps">${D.TX_STATES.map(s=>`<div class="tx-step">${s}</div>`).join('')}</div><div class="error" id="modalError"></div><div class="modal-actions"><button class="secondary-action" data-action="close">Cancel</button><button class="primary-action" data-action="confirm">Confirm in wallet</button></div></div></div>`}
  function listPage(kind){const title={entries:'My entries',outcomes:'Outcomes',refunds:'Refunds'}[kind];let body='';if(kind==='entries'){const rows=provider.getEntries();body=rows.map(r=>`<a class="table-row" href="${poolHref(r.poolId)}"><span data-label="Pool">Pool #${r.poolId}</span><span data-label="Prize">${money(r.prize)}</span><span data-label="Entries">${r.quantity} · tickets ${r.range}</span><span data-label="Entered">${money(r.amount)}</span><span data-label="Status">${r.status}</span></a>`).join('')}if(kind==='outcomes'){body=provider.getOutcomes().map(p=>`<a class="table-row" href="result.html?id=${p.id}"><span data-label="Pool">Pool #${p.id}</span><span data-label="Prize">${money(p.prize)}</span><span data-label="Winning ticket">#${p.winningTicket}</span><span data-label="Winner">${esc(p.winner)}</span><span data-label="Status">Resolved</span></a>`).join('')}if(kind==='refunds'){body=provider.getRefunds().map(r=>`<div class="table-row"><span data-label="Pool">Pool #${r.poolId}</span><span data-label="Reason">Expired before capacity</span><span data-label="Contribution">${money(r.amount)}</span><span data-label="Eligibility">${r.claimed?'Claimed':'Eligible'}</span><button class="secondary-action" data-refund="${r.poolId}" ${r.claimed?'disabled':''}>${r.claimed?'Refund claimed':'Claim refund'}</button></div>`).join('')}root.innerHTML=`${header()}<main class="demo-shell"><div class="demo-head"><div><span class="eyebrow">YOUR DEMO ACTIVITY</span><h1>${title}</h1><p class="lead">Data persists locally in this browser and is explicitly marked as demo content.</p></div></div><div class="table-card">${body||'<div class="empty">Nothing to show yet.</div>'}</div></main>`}
  function walletPage(){const w=provider.getWallet(),address=w.address?.toLowerCase(),entered=w.connected?provider.getPools().filter(p=>p.myEntries>0):[],resolved=entered.filter(p=>p.contractStatus===3),refundable=entered.filter(p=>p.contractStatus===4&&p.refundableWei>0n&&!p.refundClaimed),events=w.connected?(provider.events||[]).filter(event=>event.wallet?.toLowerCase()===address).sort((a,b)=>b.blockNumber-a.blockNumber||b.logIndex-a.logIndex):[];root.innerHTML=`${header()}<main class="demo-shell wallet-dashboard"><a href="./" class="back-link">← Pools</a><div class="demo-head"><div><span class="eyebrow">${networkLabel} / WALLET ACTIVITY</span><h1>Your wallet.</h1><p class="lead">${w.connected?`Showing onchain records for ${esc(w.address)}. Only the connected wallet can claim its prize or refund.`:'Connect a wallet to see its tickets, transactions and draw results.'}</p></div></div>${w.connected?`<div class="wallet-dashboard__summary"><div><small>ENTRIES</small><strong>${entered.reduce((n,p)=>n+p.myEntries,0)}</strong></div><div><small>DRAW RECORDS</small><strong>${resolved.length}</strong></div><div><small>REFUNDS READY</small><strong>${refundable.length}</strong></div><div><small>BNB BALANCE</small><strong>${money(w.balance)}</strong></div></div><section class="section"><div class="section-title"><h2>Your pools</h2><a href="entries.html">All entries →</a></div><div class="wallet-dashboard__cards">${entered.map(p=>`<a href="${poolHref(p.id)}"><span>POOL #${String(p.id).padStart(2,'0')}</span><strong>${money(p.prize)}</strong><small>${p.myEntries} ${p.myEntries===1?'ticket':'tickets'} · ${esc(status(p))}</small></a>`).join('')||'<div class="empty">No tickets recorded for this wallet.</div>'}</div></section><section class="section"><div class="section-title"><h2>Draw history</h2><a href="outcomes.html">All outcomes →</a></div><div class="table-card">${resolved.map(p=>`<a class="table-row" href="result.html?id=${p.id}"><span data-label="Pool">Pool #${p.id}</span><span data-label="Prize">${money(p.prize)}</span><span data-label="Your tickets">${p.myEntries} tickets</span><span data-label="Winning ticket">#${p.winningTicket}</span><span data-label="Result">${p.winner?.toLowerCase()===address?'Won':'Not selected'}</span></a>`).join('')||'<div class="empty">No completed draws for this wallet yet.</div>'}</div></section><section class="section"><div class="section-title"><h2>Transactions</h2><a href="${config.explorerUrl}/address/${esc(w.address)}" target="_blank" rel="noopener noreferrer">Full BscScan history ↗</a></div><div class="table-card">${events.slice(0,30).map(event=>`<div class="table-row"><span data-label="Pool">Pool #${event.poolId}</span><span data-label="Type">${esc(event.type==='ENTRY'?'Tickets purchased':event.text)}</span><span data-label="Amount">${event.amountWei!=null?money(Number(window.SingularOnchain.formatBNB(event.amountWei))):'—'}</span><span data-label="Time">${new Date(event.time).toLocaleString()}</span><a href="${config.explorerUrl}/tx/${esc(event.transactionHash)}" target="_blank" rel="noopener noreferrer">View tx ↗</a></div>`).join('')||`<div class="empty">${provider.logScanError?'This RPC did not return event history. Open BscScan for the complete address record.':'No pool transactions found for this wallet.'}</div>`}</div></section>`:'<div class="wallet-dashboard__connect"><p>Connect a wallet to load its onchain activity.</p><button class="primary-action" data-action="wallet-choose">Choose wallet</button></div>'}</main>`}
  function resultPage(){const p=provider.getPool(currentId());root.innerHTML=`${header()}<main class="demo-shell"><a href="outcomes.html" class="back-link">← Outcomes</a>${p&&p.status==='RESOLVED'?`<section class="demo-card" style="margin-top:24px"><div class="row-between"><div><span class="eyebrow">RESOLVED · DEMO OUTCOME</span><h1>Pool #${p.id}</h1></div><div class="result-mark">#${p.winningTicket}</div></div><div class="metrics"><div class="metric"><small>Prize</small><strong>${money(p.prize)}</strong></div><div class="metric"><small>Winner</small><strong>${esc(p.winner)}</strong></div><div class="metric"><small>Entries</small><strong>${p.entriesSold}</strong></div><div class="metric"><small>Settled</small><strong>${new Date(p.settledAt).toLocaleTimeString()}</strong></div></div><div class="notice">This result was produced by the deterministic local demo resolver. It is not a mainnet claim or transaction.</div></section>`:`<div class="empty">This pool has not resolved.</div>`}</main>`}
  function decorateOnchain(){
    if(page==='home'){
      document.querySelector('.demo-head .lead')?.replaceChildren(document.createTextNode(`Connect your wallet, inspect fixed pool terms, enter with ${unit}, and claim directly from the BNB Chain contract. No additional token is required.`));
      document.querySelector('.demo-controls')?.remove();
      const m=document.querySelectorAll('.metric');if(m[0])m[0].querySelector('small').textContent='Open testnet pools';if(m[1])m[1].querySelector('small').textContent='Confirmed entries';if(m[2]){m[2].querySelector('small').textContent='Entered tBNB';m[2].querySelector('strong').textContent=money(provider.getPools().reduce((sum,p)=>sum+p.entriesSold*p.entryPrice,0))}if(m[3])m[3].querySelector('strong').textContent='ONCHAIN';
      document.querySelector('.notice')?.replaceChildren(document.createTextNode('BNB CHAIN TESTNET ONLY · Transactions use test tBNB and gas. Not audited or available on Mainnet. Verify the Pool Manager address before signing.'));
    }
    if(page==='pool'){
      const p=provider.getPool(currentId());if(!p)return;
      const latestEntry=(p.activity||[]).find(item=>item.type==='ENTRY'),sale=recentSales.get(p.id);
      document.querySelector('.pool-hero .row-between')?.insertAdjacentHTML('afterend',`<div class="pool-live-ticker" role="status"><span class="pool-live-ticker__dot" aria-hidden="true"></span><span>${sale&&Date.now()-sale.time<30000?`${sale.quantity} new ${sale.quantity===1?'ticket':'tickets'} confirmed · `:''}${p.entriesSold} purchased · ${Math.max(0,p.capacity-p.entriesSold)} still available${latestEntry?.wallet?` · Latest buyer ${esc(D.short(latestEntry.wallet))}`:''}</span></div>`);
      const prizeHeading=document.querySelector('.pool-hero h1');if(prizeHeading)prizeHeading.textContent=money(p.prize);
      document.querySelector('.pool-hero .lead')?.replaceChildren(document.createTextNode('Fixed onchain terms. The first confirmed entry starts the timer; Chainlink VRF resolves a full pool.'));
      const activityLabel=document.querySelector('.activity-list')?.closest('.demo-card')?.querySelector('.section-title .muted');if(activityLabel)activityLabel.textContent='Confirmed testnet events';
      const positionLabel=document.querySelector('.position-grid')?.closest('.demo-card')?.querySelector('.section-title .muted');if(positionLabel)positionLabel.textContent='Connected wallet';
      const panel=document.querySelector('.entry-panel');if(panel){if(!['WAITING','LIVE','CONVERGING','NEAR RESOLUTION'].includes(status(p))){panel.innerHTML=`<span class="eyebrow">POOL #${p.id} · ${status(p)}</span><h2>${p.contractStatus===3?'Draw complete':p.contractStatus===2?'Draw in progress':'Entries closed'}</h2><p class="muted">${p.contractStatus===3?`Ticket #${p.winningTicket} was selected. The result and claim status are available below.`:p.contractStatus===2?'All tickets are sold. Waiting for the Chainlink VRF callback.':'This pool no longer accepts tickets.'}</p>${p.contractStatus===3?`<a class="secondary-action" href="result.html?id=${p.id}">View onchain result →</a>`:''}${!provider.getWallet().connected?'<button class="primary-action" data-action="connect">Connect wallet to check your claim</button>':''}<a class="secondary-action" href="${config.explorerUrl}/address/${config.poolManagerAddress}" target="_blank" rel="noreferrer">Verify Pool Manager ↗</a>`}else{const button=panel.querySelector('.primary-action');if(button)button.textContent=provider.getWallet().connected?'REVIEW ENTRY':'CONNECT WALLET';const foot=panel.querySelector('p.muted');if(foot)foot.textContent=`BNB Chain Testnet · tBNB plus gas. Transaction goes to ${config.poolManagerAddress}.`}}
      const section=document.querySelector('.detail-layout > div');
      if(p.contractStatus===2)section?.insertAdjacentHTML('beforeend',`<section class="demo-card"><span class="eyebrow">RESOLUTION PENDING</span><h2>Resolving onchain</h2><p class="muted">All tickets are confirmed. Chainlink VRF has been requested; no winner is shown before settlement. If no result arrives within 6 hours, contributors can claim refunds. No further tickets can be bought.</p></section>`);
      if(p.contractStatus===3)document.querySelector('.pool-hero')?.insertAdjacentHTML('afterend',`<section class="pool-outcome" aria-label="Pool result"><div class="pool-outcome__mark" aria-hidden="true"><span>✦</span></div><div class="pool-outcome__main"><div class="pool-outcome__heading"><span class="eyebrow">OFFICIAL DRAW RESULT / POOL #${String(p.id).padStart(2,'0')}</span><span class="pool-outcome__status">● DRAW COMPLETE</span></div><h2>One draw. One outcome.</h2><p>The winning ticket is <strong>#${p.winningTicket}</strong>. The result and payout status are read directly from the Pool Manager contract.</p><div class="pool-outcome__facts"><div><small>WINNING WALLET</small><a href="${config.explorerUrl}/address/${esc(p.winner)}" target="_blank" rel="noreferrer">${esc(D.short(p.winner))} ↗</a></div><div><small>PRIZE</small><strong>${money(p.prize)}</strong></div><div><small>PAYOUT</small><strong>${p.prizeClaimed?'CLAIMED':'AWAITING CLAIM'}</strong></div></div><div class="pool-outcome__actions"><a class="pool-outcome__link" href="result.html?id=${p.id}">View full result <span aria-hidden="true">→</span></a>${p.claimableWei>0n&&!p.prizeClaimed?`<button class="pool-outcome__claim" data-claim="${p.id}">Claim your prize <span aria-hidden="true">→</span></button>`:''}</div></div></section>`);
      if(p.contractStatus===4&&p.refundableWei>0n)section?.insertAdjacentHTML('beforeend',`<section class="demo-card"><span class="eyebrow">EXPIRED</span><h2>Refund available</h2><button class="primary-action" data-refund="${p.id}">Claim ${money(Number(window.SingularOnchain.formatBNB(p.refundableWei)))}</button></section>`);
      const modalTitle=document.querySelector('#txModal:not(:has(.receipt-card)) .eyebrow');if(modalTitle)modalTitle.textContent='BSC TESTNET TRANSACTION';const confirm=document.querySelector('#txModal [data-action="confirm"]');if(confirm)confirm.textContent='Confirm in wallet';document.querySelectorAll('#txModal .tx-step').forEach((el,i)=>el.textContent=['Awaiting signature','Submitted','Confirming','Confirmed'][i]);
    }
    if(['entries','outcomes','refunds'].includes(page)){
      document.querySelector('.demo-head .eyebrow')?.replaceChildren(document.createTextNode('BSC TESTNET ACTIVITY'));
      document.querySelector('.demo-head .lead')?.replaceChildren(document.createTextNode(page==='outcomes'?'Confirmed outcomes from the BNB Chain Testnet Pool Manager.':'Connect your wallet to see your entries and available claims on BNB Chain Testnet.'));
      if(!provider.getWallet().connected && page!=='outcomes')document.querySelector('.table-card .empty')?.replaceChildren(document.createTextNode('Connect your wallet to check this account.'));
    }
    if(page==='result'){
      const p=provider.getPool(currentId());
      if(!p){root.innerHTML=`${header()}<main class="demo-shell"><a href="outcomes.html" class="back-link">← Outcomes</a><div class="empty">Pool #${currentId()} was not found on this contract.</div></main>`;return}
      const complete=p.contractStatus===3,connected=provider.getWallet().connected,won=connected&&p.winner?.toLowerCase()===provider.getWallet().address?.toLowerCase(),owned=connected&&p.myEntries>0;
      const proofLink=p.outcomeEvent?.transactionHash?`${config.explorerUrl}/tx/${p.outcomeEvent.transactionHash}`:`${config.explorerUrl}/address/${config.poolManagerAddress}`;
      root.innerHTML=`${header()}<main class="demo-shell result-shell"><nav class="result-breadcrumb" aria-label="Breadcrumb"><a href="outcomes.html">Outcomes</a><span aria-hidden="true">/</span><span>Pool #${p.id}</span></nav><section class="result-hero"><div class="result-hero__top"><span class="eyebrow">BSC TESTNET / DRAW RECORD</span><span class="result-badge">${complete?'● DRAW COMPLETE':'● RESOLUTION PENDING'}</span></div><div class="result-hero__body"><div><h1>Pool #${String(p.id).padStart(2,'0')}<br><span>${complete?'Draw complete.':'Awaiting the outcome.'}</span></h1><p>${complete?'The winning ticket and wallet below are read directly from the Pool Manager contract.':'Entries are closed while the Chainlink VRF request is being fulfilled. No winner is displayed before settlement.'}</p></div><div class="result-prize"><small>PRIZE POOL</small><strong>${money(p.prize)}</strong><span>${complete?(p.prizeClaimed?'Prize claimed':'Winner claim available'):'Awaiting settlement'}</span></div></div></section><div class="result-summary"><div><small>WINNING TICKET</small><strong class="result-summary__ticket">${complete?'#'+p.winningTicket:'—'}</strong></div><div><small>WINNER WALLET</small>${complete?`<a class="result-address" href="${config.explorerUrl}/address/${esc(p.winner)}" target="_blank" rel="noreferrer">${esc(p.winner)} ↗</a>`:'<strong>Pending</strong>'}</div><div><small>ENTRY PRICE</small><strong>${money(p.entryPrice)}</strong></div><div><small>ENTRIES</small><strong>${p.entriesSold} / ${p.capacity}</strong></div></div><div class="result-detail-grid"><section class="result-panel"><div class="result-panel__heading"><span class="eyebrow">SETTLEMENT</span><h2>Prize status</h2></div><div class="result-payout"><span>${complete?(p.prizeClaimed?'Claimed by the winning wallet':'Ready for the winning wallet'):'Draw in progress'}</span><b>${complete?(p.prizeClaimed?'CLAIMED':'UNCLAIMED'):'PENDING'}</b></div>${owned?`<p class="result-personal">${complete?(won?'Your connected wallet holds the winning ticket.':'Your connected wallet did not hold the winning ticket.'):'Your entries will be checked after settlement.'}</p>`:''}${complete&&won&&!p.prizeClaimed&&p.claimableWei>0n?`<button class="result-action result-action--primary" data-claim="${p.id}">Claim ${money(p.prize)} <span aria-hidden="true">→</span></button>`:''}<a class="result-action" href="${proofLink}" target="_blank" rel="noreferrer">${p.outcomeEvent?'View fulfillment transaction':'View Pool Manager on BscScan'} <span aria-hidden="true">↗</span></a></section><section class="result-panel"><div class="result-panel__heading"><span class="eyebrow">VERIFICATION</span><h2>Onchain record</h2></div><div class="result-fact"><span>Network</span><b>BNB Chain Testnet</b></div><div class="result-fact"><span>Pool Manager</span><a href="${config.explorerUrl}/address/${config.poolManagerAddress}" target="_blank" rel="noreferrer">${esc(D.short(config.poolManagerAddress))} ↗</a></div><div class="result-fact"><span>Randomness request</span><b>${p.randomnessRequestId&&p.randomnessRequestId!=='0'?'Recorded onchain':'Not requested'}</b></div><details class="result-proof"><summary>Technical proof details <span aria-hidden="true">＋</span></summary><div><small>CHAINLINK REQUEST ID</small><code>${esc(p.randomnessRequestId||'—')}</code><small>RANDOM WORD</small><code>${p.outcomeEvent?esc(p.outcomeEvent.randomWord):'Unavailable from current RPC event history'}</code><p>${p.outcomeEvent?`Winning index is random word modulo ${p.capacity}.`:'The result and claim status above come directly from the contract. This RPC has not returned the fulfillment event, so the random word cannot be independently displayed here.'}</p></div></details></section></div></main>`;
    }
    if(mainnet){
      const notice=document.querySelector('.notice');
      if(page==='home'&&notice&&!location.pathname.startsWith('/legacy-app/'))notice.remove();
      if(page==='refunds')document.querySelectorAll('.table-row').forEach(row=>{const id=Number(row.querySelector('[data-label="Pool"]')?.textContent?.match(/\d+/)?.[0]);const pool=provider.getPool(id);const reason=row.querySelector('[data-label="Reason"]');if(reason&&pool?.entriesSold===pool?.capacity)reason.textContent='VRF unresolved for 6 hours';});
      if(location.pathname.startsWith('/legacy-app/')){document.querySelector('.demo-ribbon').textContent='BNB CHAIN MAINNET · PREVIOUS DEPLOYMENT';if(page==='home'&&notice)notice.innerHTML='This is the previous Pool Manager. Historical tickets and claims remain here. <a href="../mainnet-app/">Open current pools →</a>';}
      const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
      while(walker.nextNode()){
        const node=walker.currentNode;
        node.nodeValue=node.nodeValue.replaceAll('BSC TESTNET','BSC MAINNET').replaceAll('BNB Chain Testnet','BNB Chain Mainnet').replaceAll('testnet','mainnet').replaceAll('Testnet','Mainnet').replaceAll('TESTNET','MAINNET').replaceAll('tBNB','BNB');
      }
    }
  }
  function outcomeNotice(){
    document.getElementById('outcomeNotice')?.remove();
    if(!onchain||!ready)return;
    const all=provider.getPools(),states=new Map(all.map(p=>[p.id,p.contractStatus]));
    if(observedPoolStates){for(const p of all){const previous=observedPoolStates.get(p.id);if(previous!=null&&previous!==3&&p.contractStatus===3)latestSettlement=p.id}}
    observedPoolStates=states;
    const wallet=provider.getWallet(),address=wallet.address;
    let dismissed={};try{dismissed=JSON.parse(localStorage.getItem('singular:outcome-notices:v1')||'{}')}catch{}
    const personal=wallet.connected?all.filter(p=>p.myEntries>0&&([2,3].includes(p.contractStatus)||(p.contractStatus===4&&p.refundableWei>0n&&!p.refundClaimed))).sort((a,b)=>(b.contractStatus===4)-(a.contractStatus===4)||(b.contractStatus===3)-(a.contractStatus===3)||b.id-a.id):[];
    const personalPool=personal.find(pool=>!dismissed[`${config.poolManagerAddress}:${address.toLowerCase()}:${pool.id}:${pool.contractStatus}`]&&!(pool.contractStatus===3&&pool.prizeClaimed&&pool.winner.toLowerCase()===address.toLowerCase()));
    const publicPool=latestSettlement?all.find(pool=>pool.id===latestSettlement&&!dismissed[`${config.poolManagerAddress}:public:${pool.id}:3`]):null;
    const p=personalPool||publicPool;
    if(!p)return;
    const owned=!!personalPool&&p.id===personalPool.id,won=wallet.connected&&owned&&p.contractStatus===3&&p.winner.toLowerCase()===address.toLowerCase();
    const kind=p.contractStatus===4?'REFUND':p.contractStatus===2?'DRAWING':won?'WON':owned?'LOST':'COMPLETE';
    const key=owned?`${config.poolManagerAddress}:${address.toLowerCase()}:${p.id}:${p.contractStatus}`:`${config.poolManagerAddress}:public:${p.id}:3`;
    const notice=document.createElement('div');notice.id='outcomeNotice';notice.className=`outcome-notice outcome-notice--${kind.toLowerCase()} ${kind==='DRAWING'?'is-pending':''}`;
    notice.setAttribute('role',kind==='DRAWING'?'status':'alert');notice.setAttribute('aria-live','polite');
    notice.innerHTML=`<div class="outcome-notice__card"><div class="outcome-notice__beacon" aria-hidden="true"><span>${kind==='REFUND'?'↶':'✦'}</span></div><div class="outcome-notice__content"><div class="outcome-notice__meta"><span class="eyebrow">${kind==='REFUND'?'REFUND AVAILABLE':kind==='DRAWING'?'DRAW IN PROGRESS':won?'WINNING WALLET':owned?'YOUR DRAW RESULT':'DRAW COMPLETE'}</span><span>POOL #${String(p.id).padStart(2,'0')}</span></div><button class="outcome-notice__close" data-dismiss-notice="${esc(key)}" aria-label="Dismiss notification">×</button><h2>${kind==='REFUND'?'Your refund is ready.':kind==='DRAWING'?'The draw is underway.':won?'Your ticket won.':owned?'The draw is complete.':'A new result is in.'}</h2><p>${kind==='REFUND'?`Pool #${p.id} expired before filling. ${money(Number(window.SingularOnchain.formatBNB(p.refundableWei)))} is available to the connected purchasing wallet. Claiming requires your wallet confirmation and network gas.`:kind==='DRAWING'?'All entries are confirmed. Chainlink VRF is returning the onchain result.':won?`Ticket #${p.winningTicket} won ${money(p.prize)}. Claim directly with the winning wallet.`:owned?`Your tickets were not selected. Winning ticket #${p.winningTicket} is recorded onchain.`:`Pool #${p.id} has settled. Winning ticket #${p.winningTicket} is recorded onchain.`}</p><div class="outcome-notice__actions">${kind==='REFUND'?`<button class="outcome-notice__primary" data-refund="${p.id}">Claim ${money(Number(window.SingularOnchain.formatBNB(p.refundableWei)))} <span aria-hidden="true">→</span></button>`:won&&!p.prizeClaimed&&p.claimableWei>0n?`<button class="outcome-notice__primary" data-claim="${p.id}">Claim ${money(p.prize)} <span aria-hidden="true">→</span></button>`:''}<a class="outcome-notice__secondary" href="${kind==='REFUND'?'refunds.html':`result.html?id=${p.id}`}">${kind==='REFUND'?'View refunds':'View onchain result'} <span aria-hidden="true">↗</span></a></div></div></div>`;
    if(kind==='REFUND'&&p.entriesSold===p.capacity)notice.querySelector('.outcome-notice__content p').textContent=`Pool #${p.id} received no VRF result within 6 hours. ${money(Number(window.SingularOnchain.formatBNB(p.refundableWei)))} is refundable to this purchasing wallet. Claiming requires wallet confirmation and network gas.`;
    document.body.append(notice);
  }
  function cleanDisplayCopy(){
    if(!mainnet)return;
    const surfaces=[root,document.querySelector('.outcome-notice')].filter(Boolean);
    for(const surface of surfaces){
      const walker=document.createTreeWalker(surface,NodeFilter.SHOW_TEXT);
      while(walker.nextNode()){
        const node=walker.currentNode;
        if(node.parentElement?.closest('script,style,code,pre'))continue;
        const before=node.nodeValue;
        if(!before.trim())continue;
        const after=before.replace(/\.(?!\d)|(?<!\d)\./g,'').replace(/[!?;,·↗→↓↑…©“”‘’]/g,' ').replace(/:(?!\d)|(?<!\d):/g,' ').replace(/\s[-–—/]\s/g,' ').replace(/\s{2,}/g,' ');
        if(after!==before)node.nodeValue=after;
      }
    }
  }
  function render(){if(bootError){root.innerHTML=`<main class="demo-shell"><div class="notice">${networkLabel} configuration error: ${esc(bootError.message)}</div></main>`;return}if(!ready){root.innerHTML=`${header()}<main class="demo-shell"><div class="empty">Loading ${networkLabel} pools…</div></main>`;return}provider.finalizeDue();if(page==='home')home();else if(page==='pool')poolPage();else if(page==='result')resultPage();else if(page==='wallet')walletPage();else listPage(page);if(onchain){decorateOnchain();document.getElementById('walletOptions')?.replaceChildren(...walletOptionNodes())}outcomeNotice();cleanDisplayCopy();renderedWallet=`${provider.getWallet().address}:${provider.getWallet().network}`;renderedPoolStatus=page==='pool'?provider.getPool(currentId())?.contractStatus:null}
  function renderLive(){
    if(!ready||!onchain){render();return}
    const wallet=`${provider.getWallet().address}:${provider.getWallet().network}`;
    if(renderedWallet!==wallet||!root.querySelector('.demo-shell')){render();return}
    if(page==='home'){
      const all=provider.getPools(),open=all.filter(p=>!['RESOLVING','RESOLVED','EXPIRED'].includes(status(p))),drawing=all.filter(p=>status(p)==='RESOLVING');
      const grids=root.querySelectorAll('.pool-grid');
      if(!grids.length||Boolean(drawing.length)!==(grids.length>1)){render();return}
      const visible=(filter==='ALL'?open:open.filter(p=>status(p)===filter||(filter==='CONVERGING'&&status(p)==='NEAR RESOLUTION'))).sort(poolOrder);
      function updateGrid(grid,pools,empty){
        const next=pools.map(pool=>{
          const href=poolHref(pool.id),existing=[...grid.querySelectorAll(':scope > .pool-card')].find(card=>card.getAttribute('href')===href);
          const signature=`${pool.entriesSold}:${pool.contractStatus}:${pool.deadline}:${pool.myEntries}`;
          if(existing?.dataset.liveSignature===signature)return existing;
          const template=document.createElement('template');template.innerHTML=poolCard(pool);
          const card=template.content.firstElementChild;card.dataset.liveSignature=signature;return card;
        });
        if(!next.length){if(grid.querySelector('.pool-card'))grid.innerHTML=emptyPools(empty);return}
        if(next.length!==grid.children.length||next.some((node,index)=>node!==grid.children[index]))grid.replaceChildren(...next);
      }
      updateGrid(grids[0],visible,open.length>0);
      if(grids[1])updateGrid(grids[1],drawing.sort(poolOrder),false);
      const metrics=root.querySelectorAll('.metrics .metric strong');
      if(metrics[0])metrics[0].textContent=open.length;
      if(metrics[1])metrics[1].textContent=all.reduce((total,p)=>total+p.entriesSold,0);
      if(metrics[2])metrics[2].textContent=money(all.reduce((total,p)=>total+p.entriesSold*p.entryPrice,0));
      const sections=[...root.querySelectorAll('.section')];
      for(const [title,markup] of [['Recent entries',recentEntries()],['Recent outcomes',recentOutcomes()]]){
        const section=sections.find(node=>node.querySelector('h2')?.textContent===title);
        if(section){const template=document.createElement('template');template.innerHTML=markup;const next=template.content.querySelector('.table-card');if(next&&section.querySelector('.table-card')?.innerHTML!==next.innerHTML)section.querySelector('.table-card')?.replaceWith(next)}
      }
    }else if(page==='pool'){
      const pool=provider.getPool(currentId());
      if(!pool||pool.contractStatus!==renderedPoolStatus){render();return}
      const remaining=Math.max(0,pool.capacity-pool.entriesSold),fill=Math.min(100,pool.entriesSold/pool.capacity*100);
      const hero=root.querySelector('.pool-hero');
      if(hero){const line=hero.querySelector('.row-between span');if(line)line.textContent=`${pool.entriesSold} / ${pool.capacity} entries`;const bar=hero.querySelector('.progress i');if(bar)bar.style.width=`${fill}%`;const orbital=hero.querySelector('[data-singular-pool]');if(orbital)orbital.dataset.fill=String(fill);const ticker=hero.querySelector('.pool-live-ticker span:last-child');if(ticker){const sale=recentSales.get(pool.id),latest=(pool.activity||[]).find(event=>event.type==='ENTRY');ticker.textContent=`${sale&&Date.now()-sale.time<30000?`${sale.quantity} new ${sale.quantity===1?'ticket':'tickets'} confirmed · `:''}${pool.entriesSold} purchased · ${remaining} still available${latest?.wallet?` · Latest buyer ${D.short(latest.wallet)}`:''}`}}
      const remainingFact=root.querySelector('.facts .fact:last-child b');if(remainingFact)remainingFact.textContent=remaining;
      const replaceSection=(selector,markup)=>{const current=root.querySelector(selector);if(!current)return;const template=document.createElement('template');template.innerHTML=markup;const replacement=template.content.querySelector(selector);if(replacement&&current.innerHTML!==replacement.innerHTML)current.replaceWith(replacement)};
      replaceSection('.activity-list',activity(pool));
      replaceSection('.distribution',distribution(pool));
      replaceSection('.position-card',positionPanel(pool,position(pool)));
      qty=Math.max(1,Math.min(qty,Math.max(1,remaining)));
      const panel=root.querySelector('.entry-panel'),nextPanel=document.createElement('template');nextPanel.innerHTML=entryPanel(pool,position(pool),remaining,status(pool));
      if(panel&&nextPanel.content.firstElementChild&&panel.innerHTML!==nextPanel.content.firstElementChild.innerHTML)panel.replaceWith(nextPanel.content.firstElementChild);
    }else{render();return}
    const balance=root.querySelector('.wallet-menu__balance b');if(balance)balance.textContent=money(provider.getWallet().balance);
    outcomeNotice();cleanDisplayCopy();
  }
  function setTxStep(i){document.querySelectorAll('.tx-step').forEach((el,n)=>{el.className='tx-step'+(n<i?' done':n===i?' active':'')})}
  async function confirmEntry(){const btn=document.querySelector('[data-action="confirm"]');if(btn)btn.disabled=true;const poolId=currentId(),bought=qty,before=provider.getPool(poolId),previousIds=new Set(before?.myTicketIds||[]);try{let hash=null;if(onchain){const steps=['AWAITING_SIGNATURE','SUBMITTED','CONFIRMING','CONFIRMED'];const result=await provider.enterPool(poolId,bought,(state,txHash)=>{const i=steps.indexOf(state);if(i>=0)setTxStep(i);if(txHash){hash=txHash;const summary=document.getElementById('txSummary');if(summary&&!summary.querySelector('.tx-explorer-link'))summary.insertAdjacentHTML('beforeend',`<a class="tx-explorer-link" href="${config.explorerUrl}/tx/${txHash}" target="_blank" rel="noopener noreferrer">View transaction on BscScan <span>↗</span></a>`)}});hash=result.hash}else{for(let i=0;i<D.TX_STATES.length;i++){setTxStep(i);await new Promise(r=>setTimeout(r,240))}provider.enterPool(poolId,bought);setTxStep(D.TX_STATES.length);await new Promise(r=>setTimeout(r,250))}let updated;try{updated=onchain?await provider.readPool(poolId):provider.getPool(poolId)}catch(readError){console.warn('Entry confirmed; ticket read will retry:',readError);updated=provider.getPool(poolId)||before}const ids=onchain?(updated.myTicketIds||[]).filter(id=>!previousIds.has(id)):Array.from({length:bought},(_,i)=>updated.entriesSold-bought+i+1);purchaseReceipt={poolId,quantity:bought,ids,owned:onchain?(updated.myEntries||0):(position(updated)?.quantity||0),odds:D.chance(onchain?(updated.myEntries||0):(position(updated)?.quantity||0),updated.capacity).toFixed(2)+'%',cost:money(bought*updated.entryPrice),hash};modalState=null;render()}catch(e){const el=document.getElementById('modalError');if(el)el.textContent=e.message;if(btn)btn.disabled=false}}
  document.addEventListener('click',async e=>{
    const t=e.target.closest('button,[data-filter]');if(!t)return;const action=t.dataset.action;
    if(t.dataset.walletId){const choice=walletChoices.get(t.dataset.walletId);if(!choice||walletBusy)return;walletBusy=true;t.disabled=true;const error=document.getElementById('walletConnectError');if(error)error.textContent='';try{await provider.connectWallet(choice.wallet);activeWalletName=choice.name;walletDialogOpen=false;walletMenuOpen=false;localStorage.removeItem(`singular:wallet-disconnected:${config.chainId}`);localStorage.setItem(`singular:selected-wallet:${config.chainId}`,t.dataset.walletId);localStorage.setItem(`singular:selected-wallet-name:${config.chainId}`,choice.name);render()}catch(err){if(error)error.textContent=err.message;t.disabled=false}finally{walletBusy=false}return}
    if(t.dataset.filter){filter=t.dataset.filter;render();return}
    if(t.dataset.qty){qty=Number(t.dataset.qty);render();return}
    if(t.dataset.refund){t.disabled=true;t.textContent='Confirm refund in wallet…';try{if(onchain)await provider.claimRefund(t.dataset.refund);else provider.claimRefund(t.dataset.refund);if(onchain){const address=provider.getWallet().address;let dismissed={};try{dismissed=JSON.parse(localStorage.getItem('singular:outcome-notices:v1')||'{}')}catch{}dismissed[`${config.poolManagerAddress}:${address.toLowerCase()}:${t.dataset.refund}:4`]=true;try{localStorage.setItem('singular:outcome-notices:v1',JSON.stringify(dismissed))}catch{}}render()}catch(err){t.disabled=false;t.textContent='Claim refund';alert(err.message)}return}
    if(t.dataset.dismissNotice){let dismissed={};try{dismissed=JSON.parse(localStorage.getItem('singular:outcome-notices:v1')||'{}')}catch{}dismissed[t.dataset.dismissNotice]=true;try{localStorage.setItem('singular:outcome-notices:v1',JSON.stringify(dismissed))}catch{}outcomeNotice();return}
    if(t.dataset.claim){t.disabled=true;t.textContent='Confirm claim in wallet…';try{await provider.claimPrize(t.dataset.claim);render()}catch(err){t.disabled=false;t.textContent='Claim prize';alert(err.message)}return}
    if(action==='reset'&&!onchain){provider.reset();render()}
    if(action==='minus'){qty=Math.max(1,qty-1);render()}
    if(action==='plus'){qty++;render()}
    if(action==='wallet-dialog-close'){walletDialogOpen=false;document.getElementById('walletDialog')?.classList.remove('open');return}
    if(action==='wallet-choose'||(action==='connect'&&onchain)||(t.id==='walletButton'&&!provider.getWallet().connected&&onchain)){walletDialogOpen=true;document.getElementById('walletDialog')?.classList.add('open');document.getElementById('walletOptions')?.replaceChildren(...walletOptionNodes());return}
    if(action==='connect'&&!onchain){try{await provider.connectWallet();render()}catch(err){render();alert(err.message)}return}
    if(action==='review'){const p=provider.getPool(currentId()),owned=position(p)?.quantity||0;modalState=true;document.getElementById('txSummary').innerHTML=`<div class="line-item"><span>Pool</span><b>#${p.id}</b></div><div class="line-item"><span>Tickets to buy</span><b>${qty}</b></div><div class="line-item"><span>Estimated winning chance</span><b>${D.chance(owned+qty,p.capacity).toFixed(2)}%</b></div><div class="line-item"><span>Total</span><b>${money(qty*p.entryPrice)}</b></div><p class="entry-ticket-note">Ticket numbers are assigned sequentially after onchain confirmation.</p>`;document.getElementById('txModal').classList.add('is-open');setTxStep(0)}
    if(action==='close')document.getElementById('txModal')?.classList.remove('is-open');
    if(action==='close-receipt'){purchaseReceipt=null;render();document.querySelector('.position-card')?.scrollIntoView({behavior:'smooth',block:'center'});return}
    if(action==='confirm')confirmEntry();
    if(action==='disconnect'){if(onchain)localStorage.setItem(`singular:wallet-disconnected:${config.chainId}`,'1');walletMenuOpen=false;provider.disconnectWallet();render();return}
    if(action==='switch-wallet'){walletMenuOpen=false;document.getElementById('walletMenu')?.classList.remove('open');walletDialogOpen=true;document.getElementById('walletDialog')?.classList.add('open');document.getElementById('walletOptions')?.replaceChildren(...walletOptionNodes());return}
    if(action==='switch-account'){try{await provider.walletApi.request({method:'wallet_requestPermissions',params:[{eth_accounts:{}}]});await provider.connectWallet();walletMenuOpen=false;render()}catch(err){alert(err.code===-32601?'Choose another account inside your wallet, then return here.':err.message)}return}
    if(action==='copy')navigator.clipboard?.writeText(provider.getWallet().address);
    if(t.id==='walletButton'&&provider.getWallet().wrongNetwork){try{await provider.switchNetwork();await provider.refresh();render()}catch(err){alert(err.message)}return}
    if(t.id==='walletButton'&&provider.getWallet().connected){walletMenuOpen=!walletMenuOpen;document.getElementById('walletMenu')?.classList.toggle('open',walletMenuOpen);t.setAttribute('aria-expanded',String(walletMenuOpen))}
  });
  document.addEventListener('keydown',event=>{if(event.key==='Escape'){walletDialogOpen=false;walletMenuOpen=false;document.getElementById('walletDialog')?.classList.remove('open');document.getElementById('walletMenu')?.classList.remove('open')}});
  setInterval(()=>{const changed=provider.tick()|provider.finalizeDue();if(changed)render();else document.querySelectorAll('[data-timer]').forEach(el=>{const p=provider.getPool(el.dataset.timer);if(p)el.textContent=timeLeft(p)})},1000);
  if(onchain&&!bootError){
    provider.subscribe(()=>{if(provider.hasLoadedPools){trackSales();ready=true;renderLive()}});
    (async()=>{try{await provider.refresh();ready=true;if(!renderedWallet)render()}catch(error){if(provider.hasLoadedPools){ready=true;if(!renderedWallet)render();console.warn('Additional pool data unavailable:',error)}else{bootError=error;render()}}})();
    (async()=>{try{if(localStorage.getItem(`singular:wallet-disconnected:${config.chainId}`))return;const id=localStorage.getItem(`singular:selected-wallet:${config.chainId}`),name=localStorage.getItem(`singular:selected-wallet-name:${config.chainId}`);if(id||name){for(let attempt=0;attempt<10&&!walletChoices.has(id)&&![...walletChoices.values()].some(choice=>choice.name===name);attempt++)await new Promise(resolve=>setTimeout(resolve,100));const selected=walletChoices.get(id)||[...walletChoices.values()].find(choice=>choice.name===name);if(selected){provider.setWalletApi(selected.wallet);activeWalletName=selected.name}}if(await provider.restoreWallet())await provider.refresh()}catch(error){console.warn('Wallet restore unavailable:',error.message)}})();
    setInterval(()=>{if(!document.hidden)provider.syncLive().catch(error=>console.warn('BNB Chain event sync failed:',error.message))},3000);
    setInterval(()=>{if(!document.hidden)provider.refresh().catch(error=>console.warn('BNB Chain fallback refresh failed:',error.message))},60000);
    document.addEventListener('visibilitychange',()=>{if(!document.hidden)provider.syncLive().catch(()=>{})});
  }
  render();
})();
